package com.wizzadrds.theworldremembers.behavior; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import java.util.UUID; public record NpcBehaviorState(NpcActivity activity,int priority,UUID followTarget,long travelStartTick,int fatigue,long lastDecisionTick){public static final Codec<NpcBehaviorState> CODEC=RecordCodecBuilder.create(i->i.group(Codec.STRING.xmap(NpcActivity::valueOf,NpcActivity::name).fieldOf("activity").forGetter(NpcBehaviorState::activity),Codec.INT.fieldOf("priority").forGetter(NpcBehaviorState::priority),Codec.STRING.xmap(UUID::fromString,UUID::toString).optionalFieldOf("followTarget").forGetter(s->java.util.Optional.ofNullable(s.followTarget())),Codec.LONG.fieldOf("travelStartTick").forGetter(NpcBehaviorState::travelStartTick),Codec.INT.fieldOf("fatigue").forGetter(NpcBehaviorState::fatigue),Codec.LONG.fieldOf("lastDecisionTick").forGetter(NpcBehaviorState::lastDecisionTick)).apply(i,(activity,priority,target,travelStart,fatigue,last)->new NpcBehaviorState(activity,priority,target.orElse(null),travelStart,fatigue,last))); public NpcBehaviorState{fatigue=Math.max(0,Math.min(100,fatigue));} public static NpcBehaviorState idle(long tick){return new NpcBehaviorState(NpcActivity.IDLE,0,null,tick,0,tick);} public NpcBehaviorState withActivity(NpcActivity a,int p,long tick){return new NpcBehaviorState(a,p,followTarget,travelStartTick,fatigue,tick);} public NpcBehaviorState follow(UUID target,long tick){return new NpcBehaviorState(NpcActivity.FOLLOWING_PLAYER,50,target,tick,fatigue,tick);} public NpcBehaviorState stop(long tick){return new NpcBehaviorState(NpcActivity.IDLE,0,null,tick,fatigue,tick);} public NpcBehaviorState fatigue(int delta,long tick){return new NpcBehaviorState(activity,priority,followTarget,travelStartTick,Math.max(0,Math.min(100,fatigue+delta)),tick);}}
